/* Chart.js shim offline — OptiGest */
(function(global){
'use strict';
function Chart(canvas,cfg){
  this.canvas=canvas; this.cfg=cfg;
  this._draw();
}
Chart.prototype._draw=function(){
  var c=this.canvas,ctx=c.getContext('2d'),d=this.cfg.data,t=this.cfg.type,opts=(this.cfg.options||{});
  var W=c.width=c.offsetWidth||c.width||500,H=c.height=c.offsetHeight||c.height||220;
  ctx.clearRect(0,0,W,H);
  var pad={top:20,right:20,bottom:46,left:54};
  var pw=W-pad.left-pad.right, ph=H-pad.top-pad.bottom;
  var sets=d.datasets, labels=d.labels||[];
  var allVals=sets.reduce(function(a,s){return a.concat(s.data||s.points&&s.points.map(function(p){return p.y;})||[]);},[]); 
  var mn=0, mx=Math.max.apply(null,allVals)*1.12||100;
  /* grid */
  ctx.strokeStyle='rgba(31,78,121,0.08)'; ctx.lineWidth=1;
  var steps=4;
  for(var i=0;i<=steps;i++){
    var y=pad.top+ph*(1-i/steps);
    ctx.beginPath(); ctx.moveTo(pad.left,y); ctx.lineTo(pad.left+pw,y); ctx.stroke();
    ctx.fillStyle='#6B6B8A'; ctx.font='10px Arial'; ctx.textAlign='right';
    var val=(mn+(mx-mn)*i/steps);
    var lbl=opts.scales&&opts.scales.y&&opts.scales.y.ticks&&opts.scales.y.ticks.callback?opts.scales.y.ticks.callback(val.toFixed(0)):val.toFixed(0);
    ctx.fillText(lbl,pad.left-6,y+4);
  }
  /* x labels */
  ctx.fillStyle='#6B6B8A'; ctx.font='10px Arial'; ctx.textAlign='center';
  labels.forEach(function(l,i){
    var x=pad.left+(i+0.5)*(pw/labels.length);
    ctx.fillText(l,x,H-pad.bottom+16);
  });
  /* bars */
  if(t==='bar'){
    var grp=sets.length, bw=pw/labels.length/grp*0.7, gap=pw/labels.length/grp*0.3/2;
    sets.forEach(function(s,si){
      ctx.fillStyle=s.backgroundColor||'#2E75B6';
      (s.data||[]).forEach(function(v,i){
        var x=pad.left+i*(pw/labels.length)+si*(bw+gap)+gap;
        var bh=(v-mn)/(mx-mn)*ph;
        var r=Math.min(3,bw/3);
        var bx=x,by=pad.top+ph-bh,bW=bw;
        ctx.beginPath();
        ctx.moveTo(bx+r,by);ctx.lineTo(bx+bW-r,by);ctx.quadraticCurveTo(bx+bW,by,bx+bW,by+r);
        ctx.lineTo(bx+bW,by+bh);ctx.lineTo(bx,by+bh);ctx.lineTo(bx,by+r);
        ctx.quadraticCurveTo(bx,by,bx+r,by);ctx.closePath();ctx.fill();
      });
    });
  }
  /* line */
  if(t==='line'){
    sets.forEach(function(s){
      var pts=(s.data||[]).map(function(v,i){return{x:pad.left+(i+0.5)*(pw/labels.length),y:pad.top+ph-(v-mn)/(mx-mn)*ph};}).filter(function(p){return !isNaN(p.y)&&isFinite(p.y);});
      if(!pts.length)return;
      if(s.fill&&s.backgroundColor){
        ctx.beginPath();
        ctx.moveTo(pts[0].x,pad.top+ph);
        pts.forEach(function(p){ctx.lineTo(p.x,p.y);});
        ctx.lineTo(pts[pts.length-1].x,pad.top+ph);
        ctx.closePath();ctx.fillStyle=s.backgroundColor;ctx.fill();
      }
      ctx.beginPath(); ctx.strokeStyle=s.borderColor||'#2E75B6'; ctx.lineWidth=2;
      if(s.borderDash)ctx.setLineDash(s.borderDash); else ctx.setLineDash([]);
      pts.forEach(function(p,i){i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y);});
      ctx.stroke(); ctx.setLineDash([]);
      if((s.pointRadius||0)>0){
        pts.forEach(function(p){ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fillStyle=s.borderColor||'#2E75B6';ctx.fill();});
      }
    });
  }
  /* legend */
  if(sets.length>1&&opts.plugins&&opts.plugins.legend&&opts.plugins.legend.labels){
    var lx=pad.left, ly=H-8;
    sets.forEach(function(s){
      ctx.fillStyle=s.borderColor||s.backgroundColor||'#888'; ctx.fillRect(lx,ly-7,12,8);
      ctx.fillStyle='#6B6B8A'; ctx.font='10px Arial'; ctx.textAlign='left';
      ctx.fillText(s.label||'',lx+15,ly); lx+=ctx.measureText(s.label||'').width+36;
    });
  }
};
global.Chart=Chart;
})(window);
